class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def preOrder(root):
    if not root:
        return []

    result = []
    stack = [root]

    while stack:
        current = stack.pop()
        result.append(current.data)

        # Push right first so that left is processed first
        if current.right:
            stack.append(current.right)
        if current.left:
            stack.append(current.left)

    return result

# Reading input and handling output
import sys
from collections import deque

def build_tree(nodes_data):
    if not nodes_data:
        return None

    root = Node(int(nodes_data[0]))
    queue = deque([root])
    i = 1

    while queue and i < len(nodes_data):
        current = queue.popleft()

        if i < len(nodes_data):
            val = nodes_data[i]
            if val != 'null':
                current.left = Node(int(val))
                queue.append(current.left)
            i += 1

        if i < len(nodes_data):
            val = nodes_data[i + 1] if i + 1 < len(nodes_data) else None
            if val and val != 'null':
                current.right = Node(int(val))
                queue.append(current.right)
            i += 2

    return root

input_data = sys.stdin.read().split()
if input_data:
    root = build_tree(input_data)
    result = preOrder(root)
    print(" ".join(map(str, result)))
else:
    print("")
